import { announceText, createElementIf, dynamicText } from '../shared/dom-manipulation';
import { translate } from '@ps-refarch-ux/mfe-utils';
export function renderCharCounter(getCurrentAndMax) {
    return createElementIf(() => {
        const { showCharCountAttribute, maxChars } = getCurrentAndMax();
        return showCharCountAttribute !== 'false' && //we aren't showing if 'false'
            (showCharCountAttribute != null || maxChars != null); //they need to give at least one of these arguments to show
    }, 'p', {
        attrs: { class: 'neon-input-field-char-count-text' },
        text: dynamicText(() => {
            const { currentChars, maxChars } = getCurrentAndMax();
            if (maxChars == null) {
                return translate('neon|input fields|Characters') + ': ' + (currentChars || 0);
            }
            else {
                return translate('neon|input fields|Characters') + ': ' + (currentChars || 0) + '/' + maxChars;
            }
        })
    });
}
export function announceCharCountChange(showCharCountAttribute, currentChars, maxChars) {
    if (showCharCountAttribute === 'true' &&
        (currentChars != null || maxChars != null)) {
        if (maxChars == null) {
            announceText(translate('neon|input fields|Characters') + ': ' + (currentChars || 0));
        }
        else {
            announceText(translate('neon|input fields|Characters') + ': ' + (currentChars || 0) + '/' + maxChars);
        }
    }
}
